<template>
 <div class="trainer-backdrop" @keydown.esc.stop.prevent="$emit('close')" @keydown.tab="trap">
  <section ref="dialog" role="dialog" aria-modal="true" aria-labelledby="trainer-offer-name" data-trainer-offer><p class="eyebrow">RENCONTRE FACULTATIVE · {{ offer.place }}</p><h3 id="trainer-offer-name">{{ offer.name }}</h3><p>{{ offer.defeated?'Tu as déjà remporté ce défi pendant cette expédition.':offer.hint }}</p><div class="trainer-team"><div v-for="pokemon in offer.team" :key="pokemon.id"><pokemon-portrait :src="`${$assetBase}img/pokemon/front/${pokemon.id}.png`" :alt="pokemon.name"/><strong>{{ pokemon.name }}</strong><span>N. {{ offer.level }}</span></div></div><p v-if="error" role="alert">{{ error }}</p><footer><button ref="close" :disabled="busy" @click="$emit('close')">{{ offer.defeated?'Fermer':'Plus tard' }}</button><button v-if="!offer.defeated" class="challenge" :disabled="busy" data-trainer-challenge @click="$emit('challenge')">{{ busy?'Entrée en combat…':'Défier' }}</button></footer></section>
 </div>
</template>
<script>
import PokemonPortrait from '../PokemonPortrait.vue';
export default {components:{PokemonPortrait},props:{offer:Object,busy:Boolean,error:String},mounted(){this.$refs.close.focus();},methods:{trap(e){const buttons=[...this.$refs.dialog.querySelectorAll('button:not(:disabled)')];if(!buttons.length){e.preventDefault();return;}const next=e.shiftKey?buttons[buttons.length-1]:buttons[0];if(e.shiftKey?document.activeElement===buttons[0]:document.activeElement===buttons[buttons.length-1]){e.preventDefault();next.focus();}}}};
</script>
<style scoped>
.trainer-backdrop{position:fixed;inset:0;z-index:2800;display:grid;place-items:center;padding:16px;background:#0d2638b8}.trainer-backdrop section{box-sizing:border-box;width:min(460px,100%);max-height:calc(100dvh - 32px);overflow:auto;background:#f7f1df;border:2px solid #baa16a;border-radius:16px;padding:24px;color:#23454b}.eyebrow{font-size:10px;letter-spacing:.08em;color:#8b703e}h3{font:26px Georgia,serif;margin:12px 0}p{font-size:13px;line-height:1.6}.trainer-team{display:flex;justify-content:center;gap:20px;margin:24px 0}.trainer-team>div{display:grid;justify-items:center;gap:8px;font-size:13px}.trainer-team .pokemon-portrait{width:84px;height:84px}footer{display:flex;gap:10px}button{flex:1;min-height:48px;border:1px solid #94ad9a;background:#e4ebdc;color:inherit;border-radius:8px;font:inherit;cursor:pointer}.challenge{background:#286e61;color:white}button:disabled{opacity:.5}button:focus-visible{outline:3px solid #a8873b;outline-offset:3px}
</style>
